#!/bin/sh
# usage: make_bundle_x03.sh OUTDIR  (code + splits + cfgs; cfgs dir is generated by ladder.py beforehand)
set -e
O="$1"; R=$(cd "$(dirname "$0")/../.." && pwd)
rm -rf "$O"; mkdir -p "$O/v2/exp/results/X03" "$O/v2/quality" "$O/v2/entry32b" "$O/results"
cd "$R/v2/exp"; cp run_retention.py bytes.py q14.py packio.py decode_pack.py SPLITS.json ladder.py "$O/v2/exp/"; cp -r splits cfgs "$O/v2/exp/"
[ -f results/X03/sens_14b.json ] && cp results/X03/sens_14b.json "$O/v2/exp/results/X03/"
cp "$R/v2/quality/alloc.py" "$O/v2/quality/"; cp "$R/v2/entry32b/scorer.py" "$R/v2/entry32b/dev_inj.jsonl" "$O/v2/entry32b/"
cp x03_run.sh "$O/run.sh"; chmod +x "$O/run.sh"
